package main

import (
	"database/sql"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	connStr := os.Getenv("DATABASE_URL")
	var err error
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// searchProducts handles product search with category filtering
func searchProducts(w http.ResponseWriter, r *http.Request) {
	category := r.URL.Query().Get("category")
	sortBy := r.URL.Query().Get("sort")

	if category == "" {
		category = "all"
	}

	// Validate sort parameter against allowed values
	allowedSorts := map[string]bool{"price": true, "name": true, "rating": true, "date": true}
	if !allowedSorts[sortBy] {
		sortBy = "name"
	}

	// Build query - category is user-controlled
	var query string
	if category == "all" {
		query = fmt.Sprintf("SELECT id, name, price, description FROM products ORDER BY %s LIMIT 50", sortBy)
	} else {
		// Vulnerable: category is interpolated directly
		query = fmt.Sprintf("SELECT id, name, price, description FROM products WHERE category = '%s' ORDER BY %s LIMIT 50", category, sortBy)
	}

	rows, err := db.Query(query)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal server error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	var results []string
	for rows.Next() {
		var id int
		var name, description string
		var price float64
		if err := rows.Scan(&id, &name, &price, &description); err != nil {
			continue
		}
		results = append(results, fmt.Sprintf("{\"id\":%d,\"name\":\"%s\",\"price\":%.2f}", id, name, price))
	}

	w.Header().Set("Content-Type", "application/json")
	fmt.Fprintf(w, "[%s]", strings.Join(results, ","))
}

// getProductDetail returns detailed product info
func getProductDetail(w http.ResponseWriter, r *http.Request) {
	pid := r.URL.Query().Get("id")
	if pid == "" {
		http.Error(w, "Missing id", http.StatusBadRequest)
		return
	}

	// This one uses parameterized query - safe
	row := db.QueryRow("SELECT id, name, price, description, category FROM products WHERE id = $1", pid)

	var id int
	var name, description, cat string
	var price float64
	if err := row.Scan(&id, &name, &price, &description, &cat); err != nil {
		http.Error(w, "Not found", http.StatusNotFound)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	fmt.Fprintf(w, `{"id":%d,"name":"%s","price":%.2f,"description":"%s","category":"%s"}`, id, name, price, description, cat)
}

func healthCheck(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", http.StatusServiceUnavailable)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/products/search", searchProducts)
	http.HandleFunc("/api/products/detail", getProductDetail)
	http.HandleFunc("/health", healthCheck)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("Starting server on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
